package cn.mop.exportworker;

import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;

class ExportPreparationQueueTest {
    static String[] args(){return new String[]{"--run-queue-without-publication"};}
    static Map<String,String> env(){return new HashMap<>(Map.of("SPRING_PROFILES_ACTIVE","remote_test","MOP_EXPORT_PREPARATION_QUEUE_ENABLED","true","SPRING_DATASOURCE_URL","jdbc:postgresql://127.0.0.1:25439/mop_test","SPRING_DATASOURCE_USERNAME","mop_test_runtime","SPRING_DATASOURCE_PASSWORD","UNIT_ONLY_PRIVATE","MOP_EXPORT_PREPARATION_WORKER_ID","test-queue","MOP_EXPORT_PREPARATION_LEASE_MILLIS","30000","MOP_EXPORT_PREPARATION_ACCEPTED_AFTER","2026-10-14T01:00:00.000Z"));}
    @Test void explicitProspectiveModeRetainsCutoffWithoutCredentialsInToString(){var s=ExportPreparationQueueSettings.from(args(),env()::get);assertEquals(Instant.parse("2026-10-14T01:00:00Z"),s.acceptedAfter());assertEquals(Duration.ofSeconds(30),s.lease());assertFalse(s.toString().contains("UNIT_ONLY_PRIVATE"));assertFalse(s.toString().contains("jdbc:"));}
    @Test void modeMustBeExplicitAndCannotHaveImplicitJobOrExtraArguments(){for(String[] a:Arrays.asList(null,new String[0],new String[]{"--prepare-queue"},new String[]{"--run-queue-without-publication","extra"}))assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(a,env()::get));}
    @Test void rejectsMissingOrNoncanonicalCutoff(){for(String value:Arrays.asList(null,"","now","2026-10-14T09:00:00+08:00","2026-02-30T00:00:00Z","2026-10-14T00:00:60Z","2026-10-14T00:00:00.123456Z","0000-01-01T00:00:00Z")){var e=env();e.put("MOP_EXPORT_PREPARATION_ACCEPTED_AFTER",value);assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}}
    @Test void noDefaultQueueEnablementOrMixedWorkerRoles(){for(String value:Arrays.asList(null,"false","TRUE","1")){var e=env();e.put("MOP_EXPORT_PREPARATION_QUEUE_ENABLED",value);assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}for(String key:List.of("MOP_PHOTO_WORKER_ENABLED","MOP_IMPORT_WORKER_ENABLED","MOP_ASSET_IMPORT_WORKER_ENABLED","MOP_CONTACT_IMPORT_WORKER_ENABLED","MOP_EXPORT_PREPARATION_WORKER_ENABLED")){var e=env();e.put(key,"true");assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}}
    @Test void rejectsFixtureMigratorExternalDatabaseAndUrlOptions(){for(var pair:List.of(Map.entry("SPRING_PROFILES_ACTIVE","local_fixture"),Map.entry("SPRING_DATASOURCE_USERNAME","mop_test_migrator"),Map.entry("SPRING_DATASOURCE_URL","jdbc:postgresql://192.168.1.215:5432/mop_test"),Map.entry("SPRING_DATASOURCE_URL","jdbc:postgresql://127.0.0.1:5432/mop_test?password=PRIVATE"),Map.entry("SPRING_DATASOURCE_URL","jdbc:postgresql://127.0.0.1:65536/mop_test"))){var e=env();e.put(pair.getKey(),pair.getValue());assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}}
    @Test void requiresBoundedLeaseAndWorkerIdentity(){for(String value:Arrays.asList(null,"030000","999","600001","1000.0")){var e=env();e.put("MOP_EXPORT_PREPARATION_LEASE_MILLIS",value);assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}var e=env();e.put("MOP_EXPORT_PREPARATION_WORKER_ID","bad worker");assertThrows(IllegalStateException.class,()->ExportPreparationQueueSettings.from(args(),e::get));}
    @Test void unavailableDependenciesDoNotStartOrProcess(){AtomicInteger attempts=new AtomicInteger();var r=new ExportPreparationQueueRuntime(()->false,()->{attempts.incrementAndGet();return false;});assertThrows(IllegalStateException.class,r::start);assertFalse(r.running());assertEquals(0,attempts.get());}
    @Test void idlePollingBacksOffAndStopsWithoutSpinning()throws Exception{List<Long> waits=new CopyOnWriteArrayList<>();var done=new CountDownLatch(1);var r=new ExportPreparationQueueRuntime(()->true,()->false,ms->{waits.add(ms);if(waits.size()==6){done.countDown();throw new InterruptedException();}});r.start();assertTrue(done.await(2,TimeUnit.SECONDS));r.await();assertEquals(List.of(250L,500L,1000L,2000L,4000L,5000L),waits);assertFalse(r.running());}
    @Test void dependencyLossDoesNotClaimJobsAndRecoveryResumes()throws Exception{AtomicInteger probes=new AtomicInteger(),processed=new AtomicInteger();List<Long> waits=new CopyOnWriteArrayList<>();var done=new CountDownLatch(1);var r=new ExportPreparationQueueRuntime(()->{int n=probes.incrementAndGet();return n==1||n>=4;},()->{processed.incrementAndGet();return false;},ms->{waits.add(ms);if(processed.get()==1){done.countDown();throw new InterruptedException();}});r.start();assertTrue(done.await(2,TimeUnit.SECONDS));r.await();assertEquals(1,processed.get());assertEquals(List.of(1000L,2000L,250L),waits);}
    @Test void startIsIdempotentAndStopInterruptsIdleLoop()throws Exception{var entered=new CountDownLatch(1);AtomicInteger calls=new AtomicInteger();var r=new ExportPreparationQueueRuntime(()->true,()->{calls.incrementAndGet();return false;},ms->{entered.countDown();Thread.sleep(10000);});r.start();assertTrue(entered.await(2,TimeUnit.SECONDS));r.start();r.stop();r.await();assertEquals(1,calls.get());assertFalse(r.running());}
    @Test void fatalWorkerErrorDoesNotBecomeSuccessfulProcessExit()throws Exception{var r=new ExportPreparationQueueRuntime(()->true,()->{throw new AssertionError("synthetic confidential failure");});r.start();assertThrows(IllegalStateException.class,r::await);assertFalse(r.running());}
}
